mapper.sql:
WHERE d.company_id = #{f.companyId}

	AND d.merchant_id = #{f.merchantIdEq}


	AND d.distributor_id IN
	#{id}


	AND d.name LIKE CONCAT('%', #{f.nameContains}, '%')


	AND d.province = #{f.provinceEq}


	AND d.city = #{f.cityEq}


	AND d.area = #{f.areaEq}


	AND d.mobile = #{f.mobileExact}


	AND d.is_valid = #{f.isValid}

mapper.select:
SELECT d.distributor_id, d.is_distributor, d.company_id, d.mobile, d.address AS address, d.house_number, d.name AS name, d.first_letter, d.auto_sync_goods, d.logo AS logo, d.contract_phone, d.banner, d.contact AS contact, d.is_valid, d.lng, d.lat, d.child_count, d.is_default, d.province AS province, d.is_delivery, d.city AS city, d.area AS area, d.hour, d.created, d.updated, d.shop_code, d.wechat_work_department_id, d.distributor_self, d.regionauth_id, d.is_open, d.rate, d.is_dada, d.business, d.dada_shop_create, d.shansong_shop_create, d.shansong_store_id, d.merchant_id, d.distribution_type, d.is_require_subdistrict, d.is_require_building, d.delivery_distance, d.offline_aftersales, d.offline_aftersales_self, d.offline_aftersales_distributor_id, d.offline_aftersales_other, d.is_self_delivery, d.freight_time, d.is_refund_freight, d.wdt_shop_no, d.wdt_shop_id, d.jst_shop_id, d.kuaizhen_store_id, d.open_divided, d.payment_subject, d.review_status, d.dealer_id, d.split_ledger_info, d.bspay_split_ledger_info, d.source_from, d.is_open_salesman, d.show_salesperson, d.fixed_salesperson_qrcode_url, d.shop_id
ORDER BY d.created DESC, d.distributor_id ASC
LIMIT #{f.limit} OFFSET #{f.offset}
